// A seeded teaching model, not a reimplementation or validation of the research system.
export const defaults={policy:'closed-loop',family:'delay',limit:.08,rps:100,background:0,target:.99,share:.5,reserveSeconds:.1,accounting:'point',seed:51};
export const policyNames={'closed-loop':'Adaptive controller',static:'Fixed intensity',threshold:'Threshold stop','open-loop':'Preplanned intensity',paced:'Budget-paced controller'};
export const policyHints={'closed-loop':'Looks at the budget, then turns the fault up or down.',static:'Keeps the same fault intensity. The emergency guard still applies.',threshold:'Keeps intensity fixed, then stops if either SLO burns at 2× or faster.','open-loop':'Chooses intensity once using an illustrative cost, without adapting.',paced:'Turns the fault up or down by comparing spending with the pace that uses the remaining allowance on time.'};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function wilson(bad,n){if(n<=0)return[0,1];const z=1.96,p=bad/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,r=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return[Math.max(0,c-r),Math.min(1,c+r)];}
export const accountingNames={point:'Teaching point estimate',v2:'Repository v2 · realized debit','v2-credit':'Repository v2 + background credit',v1:'Retired v1 · Wilson per interval'};
// Ports src/cc_cep/uncertainty.py (Lanczos log-gamma replaces math.lgamma). Valid only under declared iid Bernoulli assumptions.
const LG=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
export function lgamma(x){if(x<.5)return Math.log(Math.PI/Math.abs(Math.sin(Math.PI*x)))-lgamma(1-x);x-=1;let a=.99999999999980993;const t=x+7.5;for(let i=0;i<8;i++)a+=LG[i]/(x+i+1);return .5*Math.log(2*Math.PI)+(x+.5)*Math.log(t)-t+Math.log(a);}
export function bernoulliLower(bad,total,alpha){if(!(alpha>0&&alpha<1)||bad<0||bad>total)throw new RangeError('invalid Bernoulli confidence inputs');if(total===0||bad===0)return 0;const logMix=lgamma(bad+.5)+lgamma(total-bad+.5)-lgamma(total+1)-2*lgamma(.5),boundary=Math.log(1/alpha);let low=0,high=bad/total;for(let i=0;i<64;i++){const p=(low+high)/2;let logE=logMix-bad*Math.log(p);if(total>bad)logE-=(total-bad)*Math.log1p(-p);if(logE>boundary)low=p;else high=p;}return low;}
export function backgroundCredit(controlBad,controlN,treatmentN,alpha=.025){const pLower=bernoulliLower(controlBad,controlN,alpha/2);if(treatmentN===0)return 0;const mean=treatmentN*pLower,logInv=Math.log(2/alpha)+2*Math.log(treatmentN)+Math.log(Math.PI**2/6);return Math.max(0,mean-Math.sqrt(2*mean*logInv));}
export function excess(tb,tn,cb,cn){return{signed:tb-tn*cb/cn,upper:tn*Math.max(0,wilson(tb,tn)[1]-wilson(cb,cn)[0])};}
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
export class Lab{
constructor(config={}){this.config={...defaults,...config};this.time=0;this.running=false;this.status='READY';this.reason='';this.intensity=0;this.exposure=0;this.events=[];this.bads=[];this.history=[];this.last=null;this.lastChange=0;this.reservedRps=this.config.rps;this.expected=this.reservedRps*120;this.reserve=this.reservedRps*this.config.reserveSeconds;this.ledgers={availability:this.ledger(1-this.config.target),latency:this.ledger(.05)};}
ledger(q){return{q,allocation:q*this.expected*this.config.share,signed:0,charged:0,totalBad:0,trueInduced:0,controlBad:0,controlN:0,treatN:0,credit:0};}
event(message){this.events.unshift({time:this.time,message});}
admit(){if(this.status!=='READY')return this.status==='RUNNING';if(Object.values(this.ledgers).some(l=>l.allocation<=this.reserve)){this.status='REJECTED';this.reason='The allowance is too small to cover the stopping reserve.';this.event('Admission rejected: reserve does not fit.');return false;}if(this.config.background>Math.min(1-this.config.target,.05)){this.status='REJECTED';this.reason='The baseline is already worse than the SLO. Start healthy before adding a fault.';this.event('Admission rejected: unhealthy baseline.');return false;}this.status='RUNNING';this.intensity=['closed-loop','paced'].includes(this.config.policy)?Math.min(.005,this.config.limit):this.config.policy==='open-loop'?Math.min(this.config.limit,...Object.values(this.ledgers).map(l=>l.allocation/this.expected)):this.config.limit;this.event('Admitted. Allocation frozen; '+this.reserve.toFixed(1)+' requests reserved for stopping.');return true;}
stop(reason){this.status='STOPPED';this.running=false;this.intensity=0;this.reason=reason;this.event(reason);}
step(){if(!this.admit())return false;const cfg=this.config;this.time++;this.intensity=Math.min(this.intensity,cfg.limit);if(['static','threshold'].includes(cfg.policy))this.intensity=cfg.limit;const applied=this.intensity;const counts={};for(const [index,cohort] of ['control','treatment'].entries()){const random=rng(cfg.seed+this.time*7919+index*104729);let a=0,l=0,ta=0,tl=0;for(let i=0;i<cfg.rps;i++){const organic=random()<cfg.background;const hit=random()<applied&&cohort==='treatment';const faultA=cfg.family==='abort'&&hit;const faultL=hit;const badA=organic||faultA;const badL=organic||faultL;a+=Number(badA);l+=Number(badL);ta+=Number(!organic&&faultA);tl+=Number(!organic&&faultL);}counts[cohort]={total:cfg.rps,availability:a,latency:l,trueAvailability:ta,trueLatency:tl};}
const burns={};const estimates={};for(const [name,ledger] of Object.entries(this.ledgers)){const c=counts.control,t=counts.treatment,e=excess(t[name],t.total,c[name],c.total);estimates[name]=e;ledger.signed+=e.signed;ledger.totalBad+=t[name];if(cfg.accounting==='v1')ledger.charged+=e.upper;else if(cfg.accounting==='point')ledger.charged+=Math.max(0,e.signed);else{ledger.controlBad+=c[name];ledger.controlN+=c.total;ledger.treatN+=t.total;ledger.credit=cfg.accounting==='v2-credit'?backgroundCredit(ledger.controlBad,ledger.controlN,ledger.treatN,.05/2):0;/* realized-cumulative-v2: high-water mark, never refunded, never above observed treatment bad events */ledger.charged=Math.max(ledger.charged,Math.max(0,ledger.totalBad-ledger.credit));}ledger.trueInduced+=t[name==='availability'?'trueAvailability':'trueLatency'];burns[name]=t[name]/t.total/ledger.q;}
this.bads.push({a:counts.treatment.availability,l:counts.treatment.latency});this.exposure+=applied;this.last={counts,burns,estimates,applied};this.history.push({time:this.time,a:clamp(100*(1-this.ledgers.availability.charged/this.ledgers.availability.allocation),0,100),l:clamp(100*(1-this.ledgers.latency.charged/this.ledgers.latency.allocation),0,100),intensity:applied*100});
for(const [name,l] of Object.entries(this.ledgers)){if(l.totalBad+this.reserve>=l.q*this.expected){this.stop('Total service budget guard: '+name+'.');return true;}if(burns[name]>=20){this.stop('Emergency stop: severe '+name+' burn.');return true;}if(l.charged+this.reserve>=l.allocation){this.stop('Allocation guard: preserving the '+name+' stopping reserve.');return true;}}
if(cfg.rps>this.reservedRps){this.stop('Traffic exceeds the admitted reserve assumption. Reset to admit this higher load.');return true;}
if(this.time>=60){this.stop('60-second experiment complete. Fault removed in this teaching model.');return true;}
if(cfg.policy==='threshold'&&Math.max(...Object.values(burns))>=2){this.stop('Threshold policy: an SLO reached 2× burn.');return true;}
if(cfg.policy==='closed-loop'&&this.time-this.lastChange>=2){const risk=Math.max(...Object.values(this.ledgers).map(l=>(l.charged/this.time)*Math.max(1,60-this.time)/Math.max(.00001,l.allocation-l.charged-this.reserve)));const recent=this.history.slice(-5); // Burn windows in the Python controller are simplified here to the current tick.
const previous=this.intensity;if(risk>1||Math.max(...Object.values(burns))>2)this.intensity*=.5;else if(risk<.5&&Math.max(...Object.values(burns))<1)this.intensity=Math.min(cfg.limit,this.intensity+.005);if(Math.abs(previous-this.intensity)>.000001){this.lastChange=this.time;this.event(this.intensity<previous?'Turned the fault down: budget pressure or high burn.':'Turned the fault up: budget headroom and low burn.');}}
if(cfg.policy==='paced'&&this.time-this.lastChange>=2){/* Simplified port of Controller.pace/_paced_step: spend relative to the pace that uses the usable allowance over the remaining window. Instant observations; 60-second horizon. */const rate=n=>{const s=this.bads.slice(-n);return{a:s.reduce((x,y)=>x+y.a,0)/s.length,l:s.reduce((x,y)=>x+y.l,0)/s.length};};const sh=rate(5),lg=rate(30),remaining=Math.max(1,60-this.time);const vals=Object.entries(this.ledgers).map(([name,l])=>{const usable=l.allocation-l.charged-this.reserve;if(usable<=0)return[Infinity,Infinity,Infinity];const key=name==='availability'?'a':'l',sustainable=usable/remaining;return[(l.charged/this.time)*remaining/usable,sh[key]/sustainable,lg[key]/sustainable];});const previous=this.intensity;if(vals.some(([r,s,g])=>r>1||(s>2&&g>1)))this.intensity*=.5;else if(vals.every(([r,s,g])=>r<.9&&s<1&&g<1))this.intensity=Math.min(cfg.limit,this.intensity+.005);if(Math.abs(previous-this.intensity)>.000001){this.lastChange=this.time;this.event(this.intensity<previous?'Paced down: spending is ahead of the pace that fits the remaining allowance.':'Paced up: spending is behind the pace that would use the allowance.');}}
return true;}
}
export function compare(config){return Object.keys(policyNames).map(policy=>{const lab=new Lab({...config,policy});for(let i=0;i<60;i++)if(!lab.step())break;return lab;});}

